/* From Uiverse.io by Sashank02 - Tags: neumorphism, card, box-shadow */
.__UIV_SCOPE__ .card {
  padding: 20px;
  width: 330px;
  min-height: 370px;
  border-radius: 20px;
  background: #e8e8e8;
  box-shadow: 5px 5px 6px #dadada,
               -5px -5px 6px #f6f6f6;
  transition: 0.4s;
}

.__UIV_SCOPE__ .card:hover {
  translate: 0 -10px;
}

.__UIV_SCOPE__ .card-title {
  font-size: 18px;
  font-weight: 600;
  color: #2e54a7;
  margin: 15px 0 0 10px;
}

.__UIV_SCOPE__ .card-image {
  min-height: 170px;
  background-color: #c9c9c9;
  border-radius: 15px;
  box-shadow: inset 8px 8px 10px #c3c3c3,
            inset -8px -8px 10px #cfcfcf;
}

.__UIV_SCOPE__ .card-body {
  margin: 13px 0 0 10px;
  color: rgb(31, 31, 31);
  font-size: 15px;
}

.__UIV_SCOPE__ .footer {
  float: right;
  margin: 28px 0 0 18px;
  font-size: 13px;
  color: #636363;
}

.__UIV_SCOPE__ .by-name {
  font-weight: 700;
}
